<script setup>
import { onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { apiClient, currentApiCacheScope } from '../../utils/api.js';
import { uploadListingMedia } from '../../api/tools/imageCropper';
const props=defineProps({shopId:{type:Number,required:true},templates:{type:Array,default:()=>[]},draft:{type:Object,default:null},card:{type:Object,default:null}}),emit=defineEmits(['close','saved']);
const clone=v=>JSON.parse(JSON.stringify(v));
const source=reactive({query:'',rows:[]});
const initial=props.draft?.payload||{subject_id:props.card?.subjectID||null,card:props.card?clone(props.card):{title:'',vendorCode:'',brand:'',description:'',dimensions:{length:null,width:null,height:null,weightBrutto:null},characteristics:[],sizes:[{techSize:'0',price:null,skus:[]}]},images:(props.card?.photos||[]).map(p=>p.big).filter(Boolean)};
const form=reactive({currency:'CNY',template_id:null,...clone(initial)}),draftId=ref(props.draft?.id||null),revision=ref(props.draft?.revision||1),busy=ref(false),attributes=ref([]),values=reactive({}),categorySearch=ref(''),categories=ref([]),imageUrl=ref(''),dragIndex=ref(-1),errors=ref([]),barcodeText=ref(form.card.sizes.map(s=>(s.skus||[]).join('\n')));
for(const item of form.card.characteristics||[])values[item.id]=Array.isArray(item.value)?item.value.join(', '):item.value;
async function run(work){if(busy.value)return;busy.value=true;const scope=currentApiCacheScope();try{await work(scope);}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{busy.value=false;}}
function applyTemplate(clear=false){const template=props.templates.find(t=>Number(t.id)===Number(form.template_id));if(!template)return;form.subject_id=Number(template.subject_id);attributes.value=template.attributes||[];if(clear){for(const key of Object.keys(values))delete values[key];for(const value of template.defaults?.characteristics||[])values[value.id]=Array.isArray(value.value)?value.value.join(', '):value.value;}form.currency='CNY';}
async function loadAttributes(){applyTemplate(false);}
function payload(){const value=clone(form);value.card.sizes=value.card.sizes.map((s,i)=>({...s,skus:barcodeText.value[i].split(/\s+/).filter(Boolean)}));value.card.characteristics=attributes.value.map(a=>({id:a.charcID,value:Number(a.charcType)===4?(values[a.charcID]===undefined||values[a.charcID]===null||values[a.charcID]===''?undefined:Number(values[a.charcID])):String(values[a.charcID]||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)})).filter(a=>a.value!==undefined&&(!Array.isArray(a.value)||a.value.length));return value;}
async function findSource(){await run(async scope=>{const r=await apiClient.get(`/api/listing/drafts?paged=1&lightweight=1&pageSize=20&query=${encodeURIComponent(source.query)}`,{noCache:true});if(scope===currentApiCacheScope())source.rows=r.rows||[];});}
async function importSource(id){await run(async scope=>{const r=await apiClient.get(`/api/wb/listing-source?shop_id=${props.shopId}&source_draft_id=${id}`,{noCache:true});if(scope!==currentApiCacheScope())return;Object.assign(form,r);barcodeText.value=form.card.sizes.map(()=>'');for(const key of Object.keys(values))delete values[key];applyTemplate(true);ElMessage.info('已引用当前草稿图片与文案；请重新选择 WB 类目、核对车型、填写 WB 售价及条码。');});}
async function save(){applyTemplate(false);const r=await apiClient.post('/api/wb/listing-drafts/save',{shop_id:props.shopId,draft_id:draftId.value,revision:revision.value,payload:payload()});draftId.value=r.draft_id;revision.value=r.revision;emit('saved');return r;}
async function saveOnly(){await run(async()=>{await save();ElMessage.success('WB 草稿已保存');emit('close');});}
async function validate(){await run(async scope=>{await save();const r=await apiClient.post('/api/wb/listing-drafts/validate',{shop_id:props.shopId,draft_id:draftId.value});if(scope!==currentApiCacheScope())return;errors.value=r.errors||[];if(r.ok)ElMessage.success('资料校验通过，可在草稿列表提交到 WB');});}
function addImage(){const url=imageUrl.value.trim();if(url&&!form.images.includes(url)&&form.images.length<30){form.images.push(url);imageUrl.value='';}}
function drop(index){const from=dragIndex.value;if(from>=0&&from!==index){const [image]=form.images.splice(from,1);form.images.splice(index,0,image);}dragIndex.value=-1;}
async function upload(options){await run(async scope=>{try{if(form.images.length>=30)throw Error('每个商品最多 30 张图片');const r=await uploadListingMedia(options.file,{source_module:'wb_listing',role:'listing_image'});if(scope!==currentApiCacheScope())return;if(r.mediaType!=='image'||!r.publishUrl)throw Error('图片未生成可公开读取的发布地址，请检查素材配置');form.images.push(r.publishUrl);options.onSuccess?.(r);}catch(e){options.onError?.(e);throw e;}});}
onMounted(()=>{if(form.template_id)applyTemplate(false);});
</script>
<template>
  <el-dialog class="wb-listing-dialog" top="3vh" :model-value="true" :title="form.card.nmID?'编辑 WB 商品草稿':'WB 商品上架 · 编辑草稿'" width="min(1040px,96vw)" :close-on-click-modal="false" destroy-on-close @close="emit('close')">
    <el-form label-position="top" :disabled="busy">
      <el-form-item v-if="!draftId&&!form.card.nmID" label="引用现有草稿"><div class="wb-inline"><el-input v-model="source.query" placeholder="输入草稿货号或商品名称" @keyup.enter="findSource"/><el-button @click="findSource">搜索草稿</el-button></div><el-table v-if="source.rows.length" :data="source.rows" max-height="240"><el-table-column prop="internal_code" label="货号" width="170"/><el-table-column prop="product_name" label="商品名称"/><el-table-column width="90"><template #default="{row}"><el-button link type="primary" @click="importSource(row.id)">引用</el-button></template></el-table-column></el-table></el-form-item>
      <el-form-item label="WB 类目模板" required><el-select v-model="form.template_id" placeholder="先导入并选择 WB 模板" @change="applyTemplate(true)"><el-option v-for="template in templates" :key="template.id" :value="Number(template.id)" :label="template.name+' · '+template.category_name"/></el-select></el-form-item>
      <el-form-item v-if="!draftId" label="引用现有商品草稿"><div class="wb-inline"><el-input v-model="source.query" placeholder="输入草稿货号或名称" @keyup.enter="findSource"/><el-button @click="findSource">搜索草稿</el-button></div><el-table v-if="source.rows.length" :data="source.rows" max-height="220"><el-table-column prop="internal_code" label="货号" width="170"/><el-table-column prop="product_name" label="商品名称"/><el-table-column width="80"><template #default="{row}"><el-button link type="primary" @click="importSource(row.id)">引用</el-button></template></el-table-column></el-table></el-form-item>
      <div class="wb-grid"><el-form-item label="商品标题" required><el-input v-model="form.card.title" :maxlength="60" show-word-limit/></el-form-item><el-form-item label="商家货号" required><el-input v-model="form.card.vendorCode" :disabled="!!draftId||!!form.card.nmID" :maxlength="72"/></el-form-item><el-form-item label="品牌"><el-input v-model="form.card.brand"/></el-form-item></div>
      <el-form-item label="商品描述"><el-input v-model="form.card.description" type="textarea" :rows="4"/></el-form-item>
      <div class="wb-grid"><el-form-item v-for="(label,key) in {length:'包装长（cm）',width:'包装宽（cm）',height:'包装高（cm）',weightBrutto:'包装重量（kg）'}" :key="key" :label="label" required><el-input-number v-model="form.card.dimensions[key]" :precision="key==='weightBrutto'?3:0" :min="key==='weightBrutto'?0.001:1"/></el-form-item></div>
      <el-divider>规格与售价</el-divider><el-table :data="form.card.sizes" border><el-table-column label="规格" min-width="130"><template #default="{row}"><el-input v-model="row.techSize" :disabled="!!row.chrtID" placeholder="无尺码填写 0"/></template></el-table-column><el-table-column label="WB 尺码" min-width="120"><template #default="{row}"><el-input v-model="row.wbSize"/></template></el-table-column><el-table-column label="售价（人民币 CNY）" min-width="160"><template #default="{row}"><el-input-number v-model="row.price" :min="1" :precision="0"/></template></el-table-column><el-table-column label="条码（每行一个）" min-width="190"><template #default="{$index}"><el-input v-model="barcodeText[$index]" type="textarea"/></template></el-table-column><el-table-column width="80"><template #default="{row,$index}"><el-button link type="danger" :disabled="!!row.chrtID||form.card.sizes.length===1" @click="form.card.sizes.splice($index,1);barcodeText.splice($index,1)">删除</el-button></template></el-table-column></el-table>
      <div class="wb-inline"><el-button :disabled="!!form.card.nmID||form.card.sizes.length>=30" @click="form.card.sizes.push({techSize:'',price:null,skus:[]});barcodeText.push('')">添加规格</el-button><span>条码可暂留空，正式提交前再生成或填写。</span></div>
      <el-divider>类目属性</el-divider><p v-if="!form.subject_id">选择 WB 类目后加载对应属性。</p><div class="wb-grid"><el-form-item v-for="attribute in attributes.filter(a=>!a.existNamedField&&Number(a.charcType)!==0&&Number(a.charcID)!==14177453)" :key="attribute.charcID" :label="attribute.name+(attribute.unitName?`（${attribute.unitName}）`:'')" :required="attribute.required"><el-input-number v-if="Number(attribute.charcType)===4" v-model="values[attribute.charcID]"/><el-input v-else v-model="values[attribute.charcID]" placeholder="多个值用逗号分隔"/></el-form-item></div>
      <el-divider>商品图片</el-divider><p>第一张为主图。拖动调整顺序；WB 要求图片至少 700 × 900 像素，最多 30 张。</p><div class="wb-inline"><el-upload :show-file-list="false" :http-request="upload" accept="image/*" :disabled="busy"><el-button>上传图片</el-button></el-upload><el-input v-model="imageUrl" placeholder="填写 HTTPS 图片直链" @keyup.enter="addImage"/><el-button @click="addImage">添加图片</el-button></div>
      <div class="wb-images"><div v-for="(image,index) in form.images" :key="index" draggable="true" @dragstart="dragIndex=index" @dragover.prevent @drop.prevent="drop(index)" @dragend="dragIndex=-1"><el-image :src="image" :preview-src-list="form.images" :initial-index="index" preview-teleported fit="cover"/><span>{{index===0?'主图':`图片 ${index+1}`}}</span><el-button link type="danger" @click="form.images.splice(index,1)">删除</el-button></div></div>
      <el-alert v-for="error in errors" :key="error" :title="error" type="error" :closable="false"/>
      <el-alert title="当前为审核阶段：保存、校验和预览草稿，不会提交 WB 上架。WB 运费和利润规则独立，待后续接入。" type="info" :closable="false"/>
    </el-form>
    <template #footer><el-button :disabled="busy" @click="emit('close')">取消</el-button><el-button :loading="busy" @click="validate">校验资料</el-button><el-button type="primary" :loading="busy" @click="saveOnly">保存草稿</el-button></template>
  </el-dialog>
</template>
<style scoped>
.wb-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.wb-inline{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.wb-inline .el-input{max-width:360px}.wb-inline .el-select{min-width:260px}.wb-images{display:flex;flex-wrap:wrap;gap:14px;margin:16px 0}.wb-images>div{width:100px;display:grid;gap:6px;cursor:grab}.wb-images .el-image{width:100px;height:132px;border-radius:var(--el-border-radius-base)}@media(max-width:640px){.wb-grid{grid-template-columns:1fr}}
</style>

<style>
.wb-listing-dialog{max-height:94vh;display:flex;flex-direction:column}.wb-listing-dialog .el-dialog__body{overflow-y:auto;flex:1;min-height:0}.wb-listing-dialog .el-dialog__footer{flex-shrink:0}
</style>
